#include <stdio.h>

static int sum_to(int limit) {
    int sum = 0;
    for (int value = 1; value <= limit; ++value) {
        sum += value;
    }
    return sum;
}

int main(void) {
    const int result = sum_to(4);
    printf("sum=%d\n", result);
    return 0;
}

#include <stdio.h>

static int count_positive(const int values[], size_t count) {
    int total = 0;
    for (size_t i = 0; i <= count; ++i) {
        if (values[i] > 0) {
            ++total;
        }
    }
    return total;
}

int main(void) {
    const int values[] = { 4, -2, 7 };
    const size_t count = sizeof values / sizeof values[0];
    printf("positive=%d\n", count_positive(values, count));
    return 0;
}
